select
from ujcms_article_i18n m join ujcms_article t on m.article_id_ = t.id_ join ujcms_article_ext uae on t.id_ = uae.id_ join ujcms_channel c on t.channel_id_ = c.id_ where m.group_id_ = #{groupId,jdbcType=BIGINT}
