select

from ujcms_article t
         join ujcms_article_ext uae on t.id_ = uae.id_
         join ujcms_channel c on t.channel_id_ = c.id_
where t.site_id_ = #{siteId,jdbcType=BIGINT}

    and t.channel_id_ = #{channelId,jdbcType=BIGINT}



    and uae.title_ like #{titlePattern}


order by t.id_ desc

select

from ujcms_article t
         join ujcms_article_ext uae on t.id_ = uae.id_
         join ujcms_channel c on t.channel_id_ = c.id_
         left join ujcms_article_i18n uai on uai.article_id_ = t.id_
where t.channel_id_ = #{channelId,jdbcType=BIGINT}
  and uai.article_id_ is null
  and t.status_ <> 20
  and (uae.title_ = #{title,jdbcType=VARCHAR}

    or t.slug_ = #{slug,jdbcType=VARCHAR}

  )
order by t.id_
